UPDATE games.game_registry r
 SET active_config_version_id=v.config_version_id,version=r.version+1,updated_at=statement_timestamp()
 FROM (VALUES
  ('dice','019a5b00-0000-7000-8000-000000000001'::uuid),
  ('scratch','019a5b00-0000-7000-8000-000000000002'::uuid),
  ('summon','019a5b00-0000-7000-8000-000000000003'::uuid),
  ('slot','019a5b00-0000-7000-8000-000000000004'::uuid),
  ('blackjack','019a5b00-0000-7000-8000-000000000005'::uuid)
 ) AS v(game_slug,config_version_id)
 WHERE r.game_slug=v.game_slug;

-- Old pre-generated commitments remain auditable but cannot cross a config boundary.
UPDATE games.fairness_commitments
 SET state='INVALIDATED'
 WHERE game_slug IN ('dice','scratch','summon','slot','blackjack') AND state='AVAILABLE';
